import { z } from "zod";

// Input schemas for /api/sessions* (docs/backend_schema.md §5).

export const MAX_MESSAGE_LENGTH = 1000;

export const startSessionSchema = z.object({ scenarioId: z.uuid() });

export const sendMessageSchema = z.object({
  /** Generated by the client per message; a repeat never creates a second message. */
  clientMessageId: z.uuid(),
  content: z.string().trim().min(1).max(MAX_MESSAGE_LENGTH),
});

/** Retry and complete take no input; the body must still be a JSON object. */
export const emptyBodySchema = z.object({});

export const idSchema = z.uuid();

export const SESSIONS_PAGE_SIZE = 20;
export const MESSAGES_PAGE_SIZE = 50;

/** ?before=<seq>&limit=<n> on GET /api/sessions/:id (older messages first page last). */
export const messagesPageSchema = z.object({
  before: z.coerce.number().int().positive().optional(),
  limit: z.coerce.number().int().min(1).max(100).default(MESSAGES_PAGE_SIZE),
});

export type StartSessionInput = z.infer<typeof startSessionSchema>;
export type SendMessageInput = z.infer<typeof sendMessageSchema>;
